INSERT INTO `constancia_templates` VALUES (1,'Constancia de Estudios','<p style=\"line-height: 1.15; text-align: center;\"><span style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Cambria, serif;\"><img src=\"data:image/png;base64,\" alt=\"Batalla_Logo_lowRes.png\" data-wrap=\"front\" data-width=\"114\" data-height=\"114\" data-top=\"97\" data-left=\"100\" style=\"position: absolute; z-index: 30; top: 97px; left: 100px; width: 114px; height: 114px;\">REPÚBLICA BOLIVARIANA DE VENEZUELA</span></p><p style=\"line-height: 1.15; text-align: center;\"><span style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Cambria, serif;\">MINISTERIO DEL PODER POPULAR PARA LA EDUCACIÓN</span></p><p style=\"line-height: 1.15; text-align: center;\"><span style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Cambria, serif;\">UNIDAD EDUCATIVA COLEGIO “BATALLA DE LA VICTORIA”</span></p><p style=\"line-height: 1.15; text-align: center;\"><span style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Cambria, serif;\">ALTAGRACIA DE ORITUCO – ESTADO GUÁRICO</span></p><p style=\"line-height: 1.15; text-align: center;\"><span style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Cambria, serif;\">CÓDIGO PLANTEL PD00801209</span></p><p style=\"line-height: 1.15; text-align: center;\"><span style=\"color: rgb(0, 0, 0); font-size: 10pt; font-family: Cambria, serif;\">RIF N° J-31007627-8</span></p><p style=\"line-height: 1.5; text-align: center;\"></p><p style=\"line-height: 1.5; text-align: center;\"></p><p style=\"line-height: 1.5; text-align: center;\"></p><p style=\"line-height: 1.5; text-align: center;\"><span style=\"color: rgb(0, 0, 0); font-size: 14pt; font-family: Cambria, serif;\"><strong>CONSTANCIA</strong></span></p><p style=\"line-height: 1.5; text-align: center;\"></p><p style=\"line-height: 1.5; text-align: center;\"><span style=\"color: rgb(0, 0, 0); font-size: 12pt; font-family: Cambria, serif;\">&nbsp;</span></p><p style=\"line-height: 2; text-align: jus