--
-- Table structure for table `evaluation_plans`
--

DROP TABLE IF EXISTS `evaluation_plans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `evaluation_plans` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `periodGradeSubjectId` int(11) NOT NULL,
  `sectionId` int(11) NOT NULL,
  `termId` int(11) NOT NULL,
  `description` varchar(255) NOT NULL,
  `percentage` decimal(5,2) NOT NULL,
  `date` date NOT NULL,
  `thematicComponentId` int(11) DEFAULT NULL,
  `thematicContentIds` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `evaluationType` varchar(255) DEFAULT NULL,
  `tecnica` varchar(255) DEFAULT NULL,
  `instrumento` varchar(255) DEFAULT NULL,
  `shortDescription` varchar(40) DEFAULT NULL,
  `tecnicaId` int(11) DEFAULT NULL,
  `instrumentoId` int(11) DEFAULT NULL,
  `estrategiaId` int(11) DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `temaGenerador` text COMMENT 'Tema generador de la evaluacion',
  `referentesTeoricos` text COMMENT 'Referentes teoricos de la evaluacion',
  `referentesEticos` text COMMENT 'Referentes eticos e indispensables',
  `estrategiaEvaluacion` text COMMENT 'Estrategia de evaluacion',
  `tipoEvaluacion` varchar(100) DEFAULT NULL COMMENT 'Tipo de evaluacion',
  `formaEvaluacion` varchar(100) DEFAULT NULL COMMENT 'Forma de evaluacion',
  `indicador` text COMMENT 'Indicador de desempeño',
  PRIMARY KEY (`id`),
  KEY `periodGradeSubjectId` (`periodGradeSubjectId`),
  KEY `termId` (`termId`),
  KEY `thematicComponentId` (`thematicComponentId`),
  KEY `tecnicaId` (`tecnicaId`),
  KEY `instrumentoId` (`instrumentoId`),
  KEY `estrategiaId` (`estrategiaId`),
  CONSTRAINT `evaluation_plans_ibfk_1` FOREIGN KEY (`periodGradeSubjectId`) REFERENCES `period_grade_subjects` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `evaluation_plans_ibfk_2` FOREIGN KEY (`termId`) REFERENCES `terms` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `evaluation_plans_ibfk_3` FOREIGN KEY (`thematicComponentId`) REFERENCES `thematic_components` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `evaluation_plans_ibfk_4` FOREIGN KEY (`tecnicaId`) REFERENCES `evaluation_catalogs` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `evaluation_plans_ibfk_5` FOREIGN KEY (`instrumentoId`) REFERENCES `evaluation_catalogs` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `evaluation_plans_ibfk_6` FOREIGN KEY (`estrategiaId`) REFERENCES `evaluation_catalogs` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1500 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

