CREATE TABLE `historical_grades` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `personId` int(11) NOT NULL,
  `gradeId` int(11) NOT NULL,
  `subjectId` int(11) NOT NULL,
  `schoolPeriodId` int(11) DEFAULT NULL,
  `finalScore` decimal(5,2) DEFAULT NULL,
  `status` enum('aprobada','reprobada') NOT NULL DEFAULT 'reprobada',
  `gradeType` enum('regular','revision','materia_pendiente','transferencia','equivalencia') NOT NULL DEFAULT 'regular',
  `plantelId` int(11) DEFAULT NULL,
  `date` date DEFAULT NULL,
  `subjectName` text,
  `createdBy` int(11) DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_historical_grades_person_grade_subject` (`personId`,`gradeId`,`subjectId`),
  KEY `gradeId` (`gradeId`),
  KEY `subjectId` (`subjectId`),
  KEY `schoolPeriodId` (`schoolPeriodId`),
  KEY `plantelId` (`plantelId`),
  KEY `createdBy` (`createdBy`),
  CONSTRAINT `historical_grades_ibfk_1` FOREIGN KEY (`personId`) REFERENCES `people` (`id`) ON DELETE CASCADE,
  CONSTRAINT `historical_grades_ibfk_2` FOREIGN KEY (`gradeId`) REFERENCES `grades` (`id`),
  CONSTRAINT `historical_grades_ibfk_3` FOREIGN KEY (`subjectId`) REFERENCES `subjects` (`id`),
  CONSTRAINT `historical_grades_ibfk_4` FOREIGN KEY (`schoolPeriodId`) REFERENCES `school_periods` (`id`),
  CONSTRAINT `historical_grades_ibfk_5` FOREIGN KEY (`plantelId`) REFERENCES `planteles` (`id`),
  CONSTRAINT `historical_grades_ibfk_6` FOREIGN KEY (`createdBy`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=143 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

