--
-- Table structure for table `inscription_subject_revisions`
--

DROP TABLE IF EXISTS `inscription_subject_revisions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `inscription_subject_revisions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `revisionPeriodId` int(11) NOT NULL,
  `inscriptionSubjectId` int(11) NOT NULL,
  `opportunity` int(11) NOT NULL DEFAULT '1',
  `score` decimal(5,2) DEFAULT NULL,
  `status` enum('pending','approved','failed') NOT NULL DEFAULT 'pending',
  `gradedBy` int(11) DEFAULT NULL,
  `gradedAt` datetime DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `isAbsent` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ins_subject_revision` (`revisionPeriodId`,`inscriptionSubjectId`,`opportunity`),
  UNIQUE KEY `uq_inscription_subject_revisions` (`revisionPeriodId`,`inscriptionSubjectId`,`opportunity`),
  KEY `inscriptionSubjectId` (`inscriptionSubjectId`),
  KEY `gradedBy` (`gradedBy`),
  KEY `inscription_subject_revisions_inscription_subject_id` (`inscriptionSubjectId`),
  CONSTRAINT `inscription_subject_revisions_ibfk_1` FOREIGN KEY (`revisionPeriodId`) REFERENCES `revision_periods` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `inscription_subject_revisions_ibfk_2` FOREIGN KEY (`inscriptionSubjectId`) REFERENCES `inscription_subjects` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `inscription_subject_revisions_ibfk_3` FOREIGN KEY (`gradedBy`) REFERENCES `people` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2340 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

