DROP TABLE IF EXISTS `inscription_subjects`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `inscription_subjects` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `inscriptionId` int(11) NOT NULL,
  `subjectId` int(11) NOT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `schoolPeriodId` int(11) DEFAULT NULL COMMENT 'Denormalizado desde Inscription.schoolPeriodId',
  `gradeId` int(11) DEFAULT NULL COMMENT 'Denormalizado desde Inscription.gradeId',
  `sectionId` int(11) DEFAULT NULL COMMENT 'Denormalizado desde Inscription.sectionId',
  PRIMARY KEY (`id`),
  UNIQUE KEY `inscription_subjects_subjectId_inscriptionId_unique` (`inscriptionId`,`subjectId`),
  UNIQUE KEY `inscription_subjects_inscription_id_subject_id` (`inscriptionId`,`subjectId`),
  KEY `subjectId` (`subjectId`),
  KEY `idx_inscription_subjects_context` (`schoolPeriodId`,`gradeId`,`subjectId`),
  CONSTRAINT `inscription_subjects_ibfk_1` FOREIGN KEY (`inscriptionId`) REFERENCES `inscriptions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `inscription_subjects_ibfk_2` FOREIGN KEY (`subjectId`) REFERENCES `subjects` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5635 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

