--
-- Table structure for table `inscriptions`
--

DROP TABLE IF EXISTS `inscriptions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `inscriptions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `schoolPeriodId` int(11) NOT NULL,
  `gradeId` int(11) NOT NULL,
  `sectionId` int(11) DEFAULT NULL,
  `personId` int(11) NOT NULL,
  `escolaridad` enum('regular','repitiente','materia_pendiente','transferencia') NOT NULL DEFAULT 'regular',
  `originPeriodId` int(11) DEFAULT NULL,
  `isRepeater` tinyint(1) NOT NULL DEFAULT '0',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `withdrawnAt` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `gradeId` (`gradeId`),
  KEY `sectionId` (`sectionId`),
  KEY `personId` (`personId`),
  KEY `originPeriodId` (`originPeriodId`),
  KEY `inscriptions_school_period_id_person_id` (`schoolPeriodId`,`personId`),
  CONSTRAINT `inscriptions_ibfk_1` FOREIGN KEY (`schoolPeriodId`) REFERENCES `school_periods` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `inscriptions_ibfk_2` FOREIGN KEY (`gradeId`) REFERENCES `grades` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `inscriptions_ibfk_3` FOREIGN KEY (`sectionId`) REFERENCES `sections` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `inscriptions_ibfk_4` FOREIGN KEY (`personId`) REFERENCES `people` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `inscriptions_ibfk_5` FOREIGN KEY (`originPeriodId`) REFERENCES `school_periods` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=538 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

