--
-- Table structure for table `matriculations`
--

DROP TABLE IF EXISTS `matriculations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `matriculations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `personId` int(11) NOT NULL,
  `schoolPeriodId` int(11) NOT NULL,
  `gradeId` int(11) NOT NULL,
  `sectionId` int(11) DEFAULT NULL,
  `escolaridad` enum('regular','repitiente','materia_pendiente') NOT NULL DEFAULT 'regular',
  `status` enum('pending','completed','withdrawn') NOT NULL DEFAULT 'pending',
  `inscriptionId` int(11) DEFAULT NULL,
  `hiddenFromControlEstudios` tinyint(1) NOT NULL DEFAULT '0',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `matriculations_school_period_id_person_id` (`schoolPeriodId`,`personId`),
  KEY `personId` (`personId`),
  KEY `gradeId` (`gradeId`),
  KEY `sectionId` (`sectionId`),
  KEY `inscriptionId` (`inscriptionId`),
  CONSTRAINT `matriculations_ibfk_1` FOREIGN KEY (`personId`) REFERENCES `people` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `matriculations_ibfk_2` FOREIGN KEY (`schoolPeriodId`) REFERENCES `school_periods` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `matriculations_ibfk_3` FOREIGN KEY (`gradeId`) REFERENCES `grades` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `matriculations_ibfk_4` FOREIGN KEY (`sectionId`) REFERENCES `sections` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `matriculations_ibfk_5` FOREIGN KEY (`inscriptionId`) REFERENCES `inscriptions` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=544 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

