--
-- Table structure for table `period_closures`
--

DROP TABLE IF EXISTS `period_closures`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `period_closures` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `schoolPeriodId` int(11) NOT NULL,
  `status` enum('draft','validating','closed','failed') NOT NULL DEFAULT 'draft',
  `initiatedBy` int(11) DEFAULT NULL,
  `startedAt` datetime DEFAULT NULL,
  `finishedAt` datetime DEFAULT NULL,
  `log` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `schoolPeriodId` (`schoolPeriodId`),
  KEY `initiatedBy` (`initiatedBy`),
  KEY `period_closures_school_period_id` (`schoolPeriodId`),
  KEY `period_closures_status` (`status`),
  CONSTRAINT `period_closures_ibfk_1` FOREIGN KEY (`schoolPeriodId`) REFERENCES `school_periods` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `period_closures_ibfk_2` FOREIGN KEY (`initiatedBy`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

