DROP TABLE IF EXISTS `planteles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `planteles` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(50) NOT NULL,
  `name` varchar(500) NOT NULL,
  `state` varchar(100) NOT NULL,
  `dependency` varchar(100) DEFAULT NULL,
  `municipality` varchar(100) DEFAULT NULL,
  `parish` varchar(100) DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `stateCode` varchar(5) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  UNIQUE KEY `code_2` (`code`),
  UNIQUE KEY `code_3` (`code`),
  UNIQUE KEY `code_4` (`code`),
  UNIQUE KEY `code_5` (`code`),
  KEY `planteles_code` (`code`),
  KEY `planteles_name` (`name`),
  KEY `planteles_state` (`state`),
  KEY `planteles_name_state` (`name`,`state`)
) ENGINE=InnoDB AUTO_INCREMENT=15185 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

