--
-- Table structure for table `qualification_audits`
--

DROP TABLE IF EXISTS `qualification_audits`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `qualification_audits` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `qualificationId` int(11) NOT NULL,
  `editedBy` int(11) NOT NULL,
  `previousScore` decimal(5,2) DEFAULT NULL,
  `newScore` decimal(5,2) NOT NULL,
  `comment` text,
  `editedAt` datetime NOT NULL,
  `editorContext` varchar(255) DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `qualificationId` (`qualificationId`),
  KEY `editedBy` (`editedBy`),
  KEY `qualification_audits_qualification_id` (`qualificationId`),
  KEY `qualification_audits_edited_by` (`editedBy`),
  CONSTRAINT `qualification_audits_ibfk_1` FOREIGN KEY (`qualificationId`) REFERENCES `qualifications` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `qualification_audits_ibfk_2` FOREIGN KEY (`editedBy`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=299 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

