DROP TABLE IF EXISTS `qualification_edit_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `qualification_edit_requests` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `qualificationId` int(11) NOT NULL COMMENT 'Qualification whose timer expired and teacher wants to edit',
  `requestedBy` int(11) NOT NULL COMMENT 'Teacher who requested permission to edit',
  `justification` text NOT NULL COMMENT 'Reason the teacher provides for needing to edit the locked grade',
  `status` enum('pending','approved','rejected') NOT NULL DEFAULT 'pending',
  `reviewedBy` int(11) DEFAULT NULL COMMENT 'Control de Estudios user who reviewed the request',
  `reviewedAt` datetime DEFAULT NULL,
  `reviewNote` text COMMENT 'Optional note from the reviewer',
  `grantedAt` datetime DEFAULT NULL COMMENT 'When the edit permission was granted (upon approval)',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `currentScore` decimal(5,2) DEFAULT NULL COMMENT 'Score at the time of the request',
  `requestedScore` decimal(5,2) DEFAULT NULL COMMENT 'Score the teacher wants to set',
  PRIMARY KEY (`id`),
  KEY `reviewedBy` (`reviewedBy`),
  KEY `qualification_edit_requests_qualification_id` (`qualificationId`),
  KEY `qualification_edit_requests_requested_by` (`requestedBy`),
  KEY `qualification_edit_requests_status` (`status`),
  CONSTRAINT `qualification_edit_requests_ibfk_1` FOREIGN KEY (`qualificationId`) REFERENCES `qualifications` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `qualification_edit_requests_ibfk_2` FOREIGN KEY (`requestedBy`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `qualification_edit_requests_ibfk_3` FOREIGN KEY (`reviewedBy`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

