DROP TABLE IF EXISTS `qualifications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `qualifications` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `evaluationPlanId` int(11) NOT NULL,
  `inscriptionSubjectId` int(11) NOT NULL,
  `score` decimal(5,2) NOT NULL,
  `remedialScore` decimal(5,2) DEFAULT NULL,
  `isAbsent` tinyint(1) NOT NULL DEFAULT '0',
  `observations` text,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `schoolPeriodId` int(11) DEFAULT NULL COMMENT 'Denormalizado desde PeriodGrade.schoolPeriodId via EvaluationPlan',
  `termId` int(11) DEFAULT NULL COMMENT 'Denormalizado desde EvaluationPlan.termId',
  `subjectId` int(11) DEFAULT NULL COMMENT 'Denormalizado desde PeriodGradeSubject.subjectId via EvaluationPlan',
  `gradeId` int(11) DEFAULT NULL COMMENT 'Denormalizado desde PeriodGrade.gradeId via EvaluationPlan',
  `sectionId` int(11) DEFAULT NULL COMMENT 'Denormalizado desde EvaluationPlan.sectionId',
  `date` date DEFAULT NULL COMMENT 'Denormalizado desde EvaluationPlan.date',
  `scoreSetAt` datetime DEFAULT NULL,
  `remedialScoreSetAt` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `qualifications_evaluation_plan_id_inscription_subject_id` (`evaluationPlanId`,`inscriptionSubjectId`),
  KEY `inscriptionSubjectId` (`inscriptionSubjectId`),
  KEY `idx_qualifications_context` (`schoolPeriodId`,`gradeId`,`subjectId`,`termId`),
  CONSTRAINT `qualifications_ibfk_1` FOREIGN KEY (`evaluationPlanId`) REFERENCES `evaluation_plans` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `qualifications_ibfk_2` FOREIGN KEY (`inscriptionSubjectId`) REFERENCES `inscription_subjects` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=42810 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

