DROP TABLE IF EXISTS `revision_grade_edit_audits`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `revision_grade_edit_audits` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `revisionId` int(11) NOT NULL COMMENT 'Revisión cuya nota fue modificada',
  `editedBy` int(11) NOT NULL COMMENT 'Usuario de Control de Estudios que realizó la modificación',
  `previousScore` decimal(5,2) DEFAULT NULL COMMENT 'Nota antes de la modificación',
  `newScore` decimal(5,2) DEFAULT NULL COMMENT 'Nota después de la modificación',
  `previousStatus` enum('pending','approved','failed') NOT NULL COMMENT 'Estado antes de la modificación',
  `newStatus` enum('pending','approved','failed') NOT NULL COMMENT 'Estado después de la modificación',
  `previousIsAbsent` tinyint(1) NOT NULL DEFAULT '0',
  `newIsAbsent` tinyint(1) NOT NULL DEFAULT '0',
  `reason` text COMMENT 'Motivo opcional de la modificación extraordinaria',
  `editedAt` datetime NOT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `revision_grade_edit_audits_revision_id` (`revisionId`),
  KEY `revision_grade_edit_audits_edited_by` (`editedBy`),
  KEY `revision_grade_edit_audits_edited_at` (`editedAt`),
  CONSTRAINT `revision_grade_edit_audits_ibfk_1` FOREIGN KEY (`revisionId`) REFERENCES `inscription_subject_revisions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `revision_grade_edit_audits_ibfk_2` FOREIGN KEY (`editedBy`) REFERENCES `people` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=latin1;
