--
-- Table structure for table `student_observations`
--

DROP TABLE IF EXISTS `student_observations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `student_observations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `inscriptionId` int(11) NOT NULL,
  `termId` int(11) NOT NULL,
  `schoolPeriodId` int(11) NOT NULL,
  `teacherId` int(11) NOT NULL,
  `text` text NOT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_observation_per_inscription_term` (`inscriptionId`,`termId`),
  KEY `termId` (`termId`),
  KEY `schoolPeriodId` (`schoolPeriodId`),
  KEY `teacherId` (`teacherId`),
  CONSTRAINT `student_observations_ibfk_1` FOREIGN KEY (`inscriptionId`) REFERENCES `inscriptions` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `student_observations_ibfk_2` FOREIGN KEY (`termId`) REFERENCES `terms` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `student_observations_ibfk_3` FOREIGN KEY (`schoolPeriodId`) REFERENCES `school_periods` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `student_observations_ibfk_4` FOREIGN KEY (`teacherId`) REFERENCES `people` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

