DROP TABLE IF EXISTS `student_period_outcomes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `student_period_outcomes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `inscriptionId` int(11) NOT NULL,
  `finalAverage` decimal(5,2) DEFAULT NULL,
  `failedSubjects` tinyint(3) unsigned NOT NULL DEFAULT '0',
  `status` enum('aprobado','materias_pendientes','reprobado') NOT NULL DEFAULT 'aprobado',
  `promotionGradeId` int(11) DEFAULT NULL,
  `graduatedAt` datetime DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `student_period_outcomes_inscription_id` (`inscriptionId`),
  KEY `promotionGradeId` (`promotionGradeId`),
  CONSTRAINT `student_period_outcomes_ibfk_1` FOREIGN KEY (`inscriptionId`) REFERENCES `inscriptions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `student_period_outcomes_ibfk_2` FOREIGN KEY (`promotionGradeId`) REFERENCES `grades` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=287 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

